mapper.select:
SELECT c.*
FROM rec_candidate c
LEFT JOIN rec_resume r ON r.candidate_id = c.id
LEFT JOIN rec_job_position j ON j.id = r.job_position_id AND j.deleted = 0

    c.deleted = 0

        AND c.name LIKE CONCAT('%', #{name}, '%')


        AND (c.name LIKE CONCAT('%', #{keyword}, '%')
             OR c.email LIKE CONCAT('%', #{keyword}, '%')
             OR c.mobile LIKE CONCAT('%', #{keyword}, '%')
             OR j.title LIKE CONCAT('%', #{keyword}, '%'))


        AND c.status = #{stage}


        AND c.source = #{source}


        AND c.education_level = #{education}


        AND c.ai_match_score >= #{aiMatchScoreMin}


        AND c.ai_match_score <= #{aiMatchScoreMax}


        AND c.years_of_experience >= #{experienceMin}


        AND c.years_of_experience <= #{experienceMax}


        AND c.city LIKE CONCAT('%', #{city}, '%')


        AND c.create_time >= #{applyDateStart}


        AND c.create_time <= CONCAT(#{applyDateEnd}, ' 23:59:59')


        AND (r.id IS NULL OR r.screening_status = #{screeningStatus})


GROUP BY c.id
ORDER BY c.create_time DESC

SELECT c.status AS stage, COUNT(*) AS count
FROM rec_candidate c
WHERE c.deleted = 0

    AND c.create_time >= #{start}


    AND c.create_time < #{end}

GROUP BY c.status

SELECT c.source AS source, COUNT(*) AS count
FROM rec_candidate c
WHERE c.deleted = 0

    AND c.create_time >= #{start}


    AND c.create_time < #{end}

GROUP BY c.source

SELECT c.source AS source, COUNT(*) AS count FROM rec_candidate c WHERE c.deleted = 0 AND c.status = 5
AND c.create_time >= #{start}
AND c.create_time < #{end}
GROUP BY c.source

SELECT c.status AS stage, c.source AS source, COUNT(*) AS count
FROM rec_candidate c
WHERE c.deleted = 0
  AND c.create_time >= #{start}
  AND c.create_time < #{end}
GROUP BY c.status, c.source
